import java.nio.charset.StandardCharsets;

class Printer {
    void print(int v) { System.out.println("number:" + v); }
    void print(String v) { System.out.println("text:" + v); }
}
public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        String[] parts = input.split("\\s+", 2);
        Printer p = new Printer();
        if (parts[0].equals("int")) p.print(Integer.parseInt(parts[1]));
        else p.print(parts[1]);
    }
}
